<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type Report={id:number;patient:{full_name:string};latitude:string;longitude:string;gps_accuracy:string;formatted_address?:string;server_received_at:string;status:string}
const items=ref<Report[]>([]), selected=ref<Report|null>(null),error=ref('');const mapUrl=computed(()=>selected.value?`https://www.openstreetmap.org/export/embed.html?layer=mapnik&marker=${selected.value.latitude}%2C${selected.value.longitude}`:'')
onMounted(async()=>{try{const r=await fetch(`${import.meta.env.VITE_API_BASE_URL??'http://127.0.0.1:8010/api/v1'}/medication-monitoring/map`,{headers:{Authorization:`Bearer ${sessionStorage.getItem('tb_token')}`,Accept:'application/json'}});const p=await r.json();if(!r.ok)throw new Error(p.message);items.value=p.data;selected.value=items.value[0]??null}catch(e){error.value=e instanceof Error?e.message:'Gagal memuat lokasi.'}})
</script>
<template><main class="admin-page"><section class="admin-content"><header><div><p>Monitoring lokasi</p><h1>Peta Bukti Minum Obat</h1></div></header><p v-if="error" class="login-error">{{error}}</p><section class="map-layout"><div class="panel"><iframe v-if="selected" :src="mapUrl" title="Peta lokasi laporan"/><p v-else>Belum ada lokasi laporan yang tersedia.</p></div><section class="panel report-list"><button v-for="item in items" :key="item.id" :class="{chosen:item.id===selected?.id}" @click="selected=item"><b>{{item.patient.full_name}}</b><span>{{item.formatted_address??`${item.latitude}, ${item.longitude}`}}</span><small>Akurasi {{item.gps_accuracy}} m · {{item.status}}</small></button></section></section></section></main></template>
